def lps(str):
    n = len(str)
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n):
        for j in range(n):
            if str[i] == str[j]:
                dp[i + 1][j + 1] = max(dp[i][j], dp[i + 1][j + 1])
    return max(dp)

