def rearrange_bigger(n):
    def get_digits(s):
        for i in range(len(s)):
            if s[i] == '0':
                continue
            yield i
    def sort_digits(s):
        for i in range(len(s)):
            if s[i] == '0':
                continue
            if s[i] < s[i + 1]:
                temp = s[i]
                s[i] = s[i + 1]
                s[i + 1] = temp
    n_str = str(n)
    digits = get_digits(n_str)
    digits.sort()
    s = ''.join(digits)
    return int(s)

